public class CodeSecurityScanConfigurationFactory(string resourceName = null, Action<Humidifier.InspectorV2.CodeSecurityScanConfiguration> factoryAction = null) : ResourceFactory<Humidifier.InspectorV2.CodeSecurityScanConfiguration>(resourceName)
{

    internal InnerCodeSecurityScanConfigurationScopeSettingsFactory ScopeSettingsFactory { get; set; }

    internal InnerCodeSecurityScanConfigurationCodeSecurityScanConfigurationFactory ConfigurationFactory { get; set; }

    protected override Humidifier.InspectorV2.CodeSecurityScanConfiguration Create()
    {
        var codeSecurityScanConfigurationResult = CreateCodeSecurityScanConfiguration();
        factoryAction?.Invoke(codeSecurityScanConfigurationResult);

        return codeSecurityScanConfigurationResult;
    }

    private Humidifier.InspectorV2.CodeSecurityScanConfiguration CreateCodeSecurityScanConfiguration()
    {
        var codeSecurityScanConfigurationResult = new Humidifier.InspectorV2.CodeSecurityScanConfiguration
        {
            GivenName = InputResourceName,
        };

        return codeSecurityScanConfigurationResult;
    }
    public override void CreateChildren(Humidifier.InspectorV2.CodeSecurityScanConfiguration result)
    {
        base.CreateChildren(result);

        result.ScopeSettings ??= ScopeSettingsFactory?.Build();
        result.Configuration ??= ConfigurationFactory?.Build();
    }

} // End Of Class

